input.command:
dev-browser --headless --timeout 90 <<'EOF'
const page = await browser.getPage("nocturne");
const logs = [];
page.on("console", m => logs.push(m.type() + ": " + m.text()));
page.on("pageerror", e => logs.push("PAGEERROR: " + e.message));

// Motion at key beats
await page.evaluate(() => { window.__LIVING_IDENTITY__.setMode("motion"); window.__LIVING_IDENTITY__.seek(3200); });
await page.waitForTimeout(150);
const m1 = await saveScreenshot(await page.screenshot(), "motion-3200.png");
await page.evaluate(() => window.__LIVING_IDENTITY__.seek(7900));
await page.waitForTimeout(150);
const m2 = await saveScreenshot(await page.screenshot(), "motion-7900.png");
await page.evaluate(() => window.__LIVING_IDENTITY__.seek(9300));
await page.waitForTimeout(150);
const m3 = await saveScreenshot(await page.screenshot(), "motion-9300.png");
await page.evaluate(() => window.__LIVING_IDENTITY__.seek(11800));
await page.waitForTimeout(150);
const m4 = await saveScreenshot(await page.screenshot(), "motion-11800.png");

// Instrument with a real drag
await page.evaluate(() => window.__LIVING_IDENTITY__.setMode("instrument"));
await page.mouse.move(400, 500);
await page.mouse.down();
for (let i = 0; i <= 10; i++) {
  await page.mouse.move(400 + i * 60, 500 + Math.sin(i) * 120, { steps: 4 });
  await page.waitForTimeout(30);
}
await page.mouse.up();
await page.keyboard.press("2");
await page.keyboard.press(" ");
await page.waitForTimeout(300);
const i1 = await saveScreenshot(await page.screenshot(), "instrument.png");
const snap = await page.evaluate(() => window.__LIVING_IDENTITY__.snapshot());
console.log(JSON.stringify({ m1, m2, m3, m4, i1, resonators: snap.instrument.resonatorCount, voice: snap.instrument.voiceName, consoleLogs: logs }, null, 2));
EOF

